/**
 * 키보드의 입력중 숫자 값만을 허용하는 함수
 * TODO: 한글입력을 막아야 함.
 *
 * @param object event(onKeyPress)
 *
 * @return 숫자가 아닌 경우 키보드의 입력을 취소한다.
 */
/**
 * @method
 * @name fn_OnlyNum
 * @description desc
 * @param {string} event desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_OnlyNum = function(event) {
    if (window.event) {
        event = window.event;
    }
    var charCode = (event.charCode || event.charCode == 0) ? event.charCode : ((event.keyCode) ? event.keyCode : event.which);
    if (charCode == 8 || charCode == 16 || charCode == 47 || charCode == 109 || charCode == 189) {
        //백스페이스키와 del, '.'키는 먹게한다.
        //alert(charCode);
        event.returnValue = true;
    }
    if ((charCode >= 48) && (charCode <= 57)) /* 숫자  0~9 */ {
        event.returnValue = true;
    } else {
        event.returnValue = false;
    }
};




/*=============================================================================* 
 * 길이가1인 경우 앞에 "0"을 붙인다.
 * 
 * param : sVal 입력스트링
 *
 * return : String  "0"값을 포함하는 값
 *============================================================================*/
/**
 * @method
 * @name fn_AddZero
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_AddZero = function(sVal) {
    var iLen = sVal.length; //인수값의 길이를 구한다.

    if (iLen == 1) {
        sVal = "0" + sVal;
    } else if (iLen == 0) {
        return "";
    }
    return sVal;
};

//아래는 긴급하게 적용했음.
//- 처리 및 소수점까지 다 허용하게 만듬.
/**
 * @method
 * @name fn_NumberFormat
 * @description desc
 * @param {string} numstr desc
 * @param {string} ret desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_NumberFormat = function(numstr, ret) {
    if (numstr != null && numstr != '') {
        numstr = scwin.fn_SetComma(scwin.fn_DelComma(numstr));
        if (ret) ret.setValue(numstr);
        return numstr;
    }
};



// 숫자에 콤마를 찍는다.
/**
 * @method
 * @name fn_SetComma
 * @description desc
 * @param {string} numstr desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_SetComma = function(numstr) {
    numstr = String(numstr);
    var re0 = /^(-?\d+)(\d{3})($|\..*$)/;
    if (re0.test(numstr)) return numstr.replace(re0, function(str, p1, p2, p3) {
        return scwin.fn_SetComma(p1) + ',' + p2 + p3;
    });

    else return numstr;
};
String.prototype.fn_SetComma = function() {
    return scwin.fn_SetComma(this);
};
/**
 * @method
 * @name fn_ObjValueSetComma
 * @description desc
 * @param {string} numObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ObjValueSetComma = function(numObj) {
    if (numObj != null && numObj != '') {
        var tmp = numObj.getValue();
        if (tmp.substring(0, 1) == '.') {
            numObj.setValue('0' + numObj.getValue());
        }
        numObj.setValue(scwin.fn_SetComma(numObj.getValue()));
    }
};
/**
 * @method
 * @name fn_ValueSetComma
 * @description desc
 * @param {string} txtVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ValueSetComma = function(txtVal) {
    if (txtVal != null && txtVal != '') {
        if (txtVal.substring(0, 1) == '.') {
            txtVal = '0' + txtVal;
        }
        return scwin.fn_SetComma(txtVal);
    } else return '';
};
/**
 * @method
 * @name fn_ObjValueResetRmComma
 * @description desc
 * @param {string} numObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ObjValueResetRmComma = function(numObj) {
    if (numObj != null && numObj != '') {
        numObj.setValue(scwin.fn_RmComma(numObj.getValue()));
    }
};



//fn_ObjValueResetRmComma 함수 사용시, null값인 경우 0으로 데이터 넣어버리는 문제 있어서 별도 함수 사용.
/**
 * @method
 * @name fn_ObjValueResetRmComma2
 * @description desc
 * @param {string} numObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ObjValueResetRmComma2 = function(numObj) {
    if (numObj != null && numObj.getValue().length > 0) {
        numObj.setValue(scwin.fn_RmComma(numObj.getValue()));
    }
};




//컴마제거
/**
 * @method
 * @name fn_RmComma
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_RmComma = function(str) {
    //	if( str == null || str == "" || str == 0 ) return '';
    //	if( str == null || str == ""  ) return '';
    if (str == null || str == "") return Number(str); //2009.07.02 수정. 항목 미입력시 합계 오류발생

    reg = new RegExp(",", "g");
    return Number(str.replace(reg, ''));
};


// 문자를 숫자로 정리한다.
/**
 * @method
 * @name fn_DelComma
 * @description desc
 * @param {string} numstr desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_DelComma = function(numstr) {
    numstr = String(numstr);
    if (numstr == '') return '';
    //else if (numstr == '-') return '';

    else if (numstr == '0-') return '';
    numstr = numstr.replace(/[^\d\.-]/g, '');
    numstr = String(numstr.match(/^-?\d*\.?\d*/));
    numstr = numstr.replace(/^(-?)(\d*)(.*)/, function(str, p1, p2, p3) {
        p2 = (p2 > 0) ? String(p2.match(/[1-9]\d*$/)) : '0';
        //	p2 = (p2>0) ? String(parseInt(p2,10)) : '0';
        return p1 + p2 + p3;
    });
    return numstr;
};
String.prototype.fn_DelComma = function() {
    return scwin.fn_DelComma(this);
};

