/**
 * @method
 * @name fn_checkNum
 * @description desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_checkNum = function(obj) {
    val = obj.getValue();
    re = /[^0-9]/gi;
    obj.setValue(val.replace(re, ""));
};


/* 숫자포멧 설정 함수 */
/**
 * @method
 * @name fn_checkNumFormat
 * @description desc
 * @param {string} obj desc
 * @param {string} len desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_checkNumFormat = function(obj, len) {
    /* 음수 부호를 받을 변수 */
    var pre = '';
    /* 소수점 이하 값을 받을 변수 */
    var aft = '';
    if (obj.getValue().length > 0) {
        if (obj.getValue().charAt(0) == '-') pre = '-';
    }

    /* 소수점 입력인 경우 */
    if (obj.getValue().indexOf('.') > 0) {
        aft = obj.getValue().substring(obj.getValue().indexOf('.'));
    }

    /* 파라미터고 2자리인 경우 */
    if (arguments.length == 2)
        /* 넘겨받은 파라미터 값만큼 소수점 자리수를 허용 */
        if (aft.replace(/[^\d]/g, '').length > len) aft = aft.replace(/[^\d]/g, '').substring(0, len);

    /* 값을 변경 후 저장 */
    obj.setValue(pre + (Number(obj.getValue().replace(/\..*|[^\d]/g, ''))) + (aft == '' ? '' : '.' + aft.replace(/[^\d]/g, '')));
    //    obj.value = pre+(obj.value.replace(/\..*|[^\d]/g,'')).toCommify()+(aft==''?'':'.'+aft.replace(/[^\d]/g,''));

    scwin.fn_NumberFormat(obj.getValue(), obj);
};


/* scriptwin 님의 3자리 단위 컴파 표시 참조 */
String.prototype.toCommify = Number.prototype.toCommify = function() {
    var n = String(this).replace(/\,/g, '');
    //    return n.match(RegExp('^[0-9]{'+(n.length%3||3)+'}|[0-9]{3}','g'))==null?'':n.match(RegExp('^[0-9]{'+(n.length%3||3)+'}|[0-9]{3}','g'));
    return n;
};
